module ietf-interfaces {
  namespace "urn:ietf:params:xml:ns:yang:ietf-interfaces";
  prefix if;

  organization
    "IETF NETMOD (Network Modeling) Working Group";
  contact
    "WG Web:   <https://datatracker.ietf.org/wg/netmod/>
     WG List:  <mailto:netmod@ietf.org>

     Editor:   Martin Bjorklund
               <mailto:mbj@tail-f.com>";
  description
    "This module contains a collection of YANG definitions for
     managing network interfaces.

     Copyright (c) 2018 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC 8343; see
     the RFC itself for full legal notices.";

  revision 2018-02-20;

  identity interface-type {
    description
      "Base identity from which specific interface types are
       derived.";
  }

  container interfaces {
    config true;
    status current;
    description
      "Interface parameters.";
    list interface {
      key "name";
      config true;
      min-elements 0;
      max-elements 4294967295;
      ordered-by system;
      status current;
      description
        "The list of interfaces on the device.

         The status of an interface is available in this list in the
         operational state.  If the configuration of a
         system-controlled interface cannot be used by the system
         (e.g., the interface hardware present does not match the
         interface type), then the configuration is not applied to
         the system-controlled interface shown in the operational
         state.  If the configuration of a user-controlled interface
         cannot be used by the system, the configured interface is
         not instantiated in the operational state.

         System-controlled interfaces created by the system are
         always present in this list in the operational state,
         whether or not they are configured.";
      leaf name {
        type string;
        config true;
        status current;
        description
          "The name of the interface.

           A device MAY restrict the allowed values for this leaf,
           possibly depending on the type of the interface.
           For system-controlled interfaces, this leaf is the
           device-specific name of the interface.

           If a client tries to create configuration for a
           system-controlled interface that is not present in the
           operational state, the server MAY reject the request if
           the implementation does not support pre-provisioning of
           interfaces or if the name refers to an interface that can
           never exist in the system.  A Network Configuration
           Protocol (NETCONF) server MUST reply with an rpc-error
           with the error-tag 'invalid-value' in this case.

           If the device supports pre-provisioning of interface
           configuration, the 'pre-provisioning' feature is
           advertised.

           If the device allows arbitrarily named user-controlled
           interfaces, the 'arbitrary-names' feature is advertised.

           When a configured user-controlled interface is created by
           the system, it is instantiated with the same name in the
           operational state.

           A server implementation MAY map this leaf to the ifName
           MIB object.  Such an implementation needs to use some
           mechanism to handle the differences in size and characters
           allowed between this leaf and ifName.  The definition of
           such a mechanism is outside the scope of this document.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifName";
      }
      leaf description {
        type string;
        config true;
        status current;
        description
          "A textual description of the interface.

           A server implementation MAY map this leaf to the ifAlias
           MIB object.  Such an implementation needs to use some
           mechanism to handle the differences in size and characters
           allowed between this leaf and ifAlias.  The definition of
           such a mechanism is outside the scope of this document.

           Since ifAlias is defined to be stored in non-volatile
           storage, the MIB implementation MUST map ifAlias to the
           value of 'description' in the persistently stored
           configuration.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifAlias";
      }
      leaf type {
        type identityref {
          base interface-type;
        }
        config true;
        mandatory true;
        status current;
        description
          "The type of the interface.

           When an interface entry is created, a server MAY
           initialize the type leaf with a valid value, e.g., if it
           is possible to derive the type from the name of the
           interface.

           If a client tries to set the type of an interface to a
           value that can never be used by the system, e.g., if the
           type is not supported or if the type does not match the
           name of the interface, the server MUST reject the request.
           A NETCONF server MUST reply with an rpc-error with the
           error-tag 'invalid-value' in this case.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifType";
      }
      leaf enabled {
        type boolean;
        default "true";
        config true;
        status current;
        description
          "This leaf contains the configured, desired state of the
           interface.

           Systems that implement the IF-MIB use the value of this
           leaf in the intended configuration to set
           IF-MIB.ifAdminStatus to 'up' or 'down' after an ifEntry
           has been initialized, as described in RFC 2863.

           Changes in this leaf in the intended configuration are
           reflected in ifAdminStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifAdminStatus";
      }
      leaf link-up-down-trap-enable {
        type enumeration {
          enum "enabled" {
            value 1;
            status current;
            description
              "The device will generate linkUp/linkDown SNMP
               notifications for this interface.";
          }
          enum "disabled" {
            value 2;
            status current;
            description
              "The device will not generate linkUp/linkDown SNMP
               notifications for this interface.";
          }
        }
        config true;
        status current;
        description
          "Controls whether linkUp/linkDown SNMP notifications
           should be generated for this interface.

           If this node is not configured, the value 'enabled' is
           operationally used by the server for interfaces that do
           not operate on top of any other interface (i.e., there are
           no 'lower-layer-if' entries), and 'disabled' otherwise.";
        reference
          "RFC 2863: The Interfaces Group MIB -
                     ifLinkUpDownTrapEnable";
      }
      leaf admin-status {
        type enumeration {
          enum "up" {
            value 1;
            status current;
            description
              "Ready to pass packets.";
          }
          enum "down" {
            value 2;
            status current;
            description
              "Not ready to pass packets and not in some test mode.";
          }
          enum "testing" {
            value 3;
            status current;
            description
              "In some test mode.";
          }
        }
        config false;
        mandatory true;
        status current;
        description
          "The desired state of the interface.

           This leaf has the same read semantics as ifAdminStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifAdminStatus";
      }
      leaf oper-status {
        type enumeration {
          enum "up" {
            value 1;
            status current;
            description
              "Ready to pass packets.";
          }
          enum "down" {
            value 2;
            status current;
            description
              "The interface does not pass any packets.";
          }
          enum "testing" {
            value 3;
            status current;
            description
              "In some test mode.  No operational packets can
               be passed.";
          }
          enum "unknown" {
            value 4;
            status current;
            description
              "Status cannot be determined for some reason.";
          }
          enum "dormant" {
            value 5;
            status current;
            description
              "Waiting for some external event.";
          }
          enum "not-present" {
            value 6;
            status current;
            description
              "Some component (typically hardware) is missing.";
          }
          enum "lower-layer-down" {
            value 7;
            status current;
            description
              "Down due to state of lower-layer interface(s).";
          }
        }
        config false;
        mandatory true;
        status current;
        description
          "The current operational state of the interface.

           This leaf has the same semantics as ifOperStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifOperStatus";
      }
      leaf last-change {
        type string {
          pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
        }
        config false;
        status current;
        description
          "The time the interface entered its current operational
           state.  If the current state was entered prior to the
           last re-initialization of the local network management
           subsystem, then this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifLastChange";
      }
      leaf if-index {
        type int32 {
          range "1..2147483647";
        }
        config false;
        mandatory true;
        status current;
        description
          "The ifIndex value for the ifEntry represented by this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifIndex";
      }
      leaf phys-address {
        type string {
          pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
        }
        config false;
        status current;
        description
          "The interface's address at its protocol sub-layer.  For
           example, for an 802.x interface, this object normally
           contains a Media Access Control (MAC) address.  The
           interface's media-specific modules must define the bit
           and byte ordering and the format of the value of this
           object.  For interfaces that do not have such an address
           (e.g., a serial line), this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifPhysAddress";
      }
      leaf-list higher-layer-if {
        type leafref {
          path "/if:interfaces/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "A list of references to interfaces layered on top of this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf-list lower-layer-if {
        type leafref {
          path "/if:interfaces/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "A list of references to interfaces layered underneath this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf speed {
        type uint64;
        units "bits/second";
        config false;
        status current;
        description
          "An estimate of the interface's current bandwidth in bits
           per second.  For interfaces that do not vary in
           bandwidth or for those where no accurate estimation can
           be made, this node should contain the nominal bandwidth.
           For interfaces that have no concept of bandwidth, this
           node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB -
                     ifSpeed, ifHighSpeed";
      }
      container statistics {
        config false;
        status current;
        description
          "A collection of interface-related statistics objects.";
        leaf discontinuity-time {
          type string {
            pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
          }
          config false;
          mandatory true;
          status current;
          description
            "The time on the most recent occasion at which any one or
             more of this interface's counters suffered a
             discontinuity.  If no such discontinuities have occurred
             since the last re-initialization of the local management
             subsystem, then this node contains the time the local
             management subsystem re-initialized itself.";
        }
        leaf in-octets {
          type uint64;
          config false;
          status current;
          description
            "The total number of octets received on the interface,
             including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInOctets";
        }
        leaf in-unicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were not addressed to a
             multicast or broadcast address at this sub-layer.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInUcastPkts";
        }
        leaf in-broadcast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a broadcast
             address at this sub-layer.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInBroadcastPkts";
        }
        leaf in-multicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a multicast
             address at this sub-layer.  For a MAC-layer protocol,
             this includes both Group and Functional addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInMulticastPkts";
        }
        leaf in-discards {
          type uint32;
          config false;
          status current;
          description
            "The number of inbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being deliverable to a higher-layer
             protocol.  One possible reason for discarding such a
             packet could be to free up buffer space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInDiscards";
        }
        leaf in-errors {
          type uint32;
          config false;
          status current;
          description
            "For packet-oriented interfaces, the number of inbound
             packets that contained errors preventing them from being
             deliverable to a higher-layer protocol.  For character-
             oriented or fixed-length interfaces, the number of
             inbound transmission units that contained errors
             preventing them from being deliverable to a higher-layer
             protocol.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInErrors";
        }
        leaf in-unknown-protos {
          type uint32;
          config false;
          status current;
          description
            "For packet-oriented interfaces, the number of packets
             received via the interface that were discarded because
             of an unknown or unsupported protocol.  For
             character-oriented or fixed-length interfaces that
             support protocol multiplexing, the number of
             transmission units received via the interface that were
             discarded because of an unknown or unsupported protocol.
             For any interface that does not support protocol
             multiplexing, this counter is not present.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInUnknownProtos";
        }
        leaf out-octets {
          type uint64;
          config false;
          status current;
          description
            "The total number of octets transmitted out of the
             interface, including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutOctets";
        }
        leaf out-unicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were not addressed
             to a multicast or broadcast address at this sub-layer,
             including those that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutUcastPkts";
        }
        leaf out-broadcast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             broadcast address at this sub-layer, including those
             that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutBroadcastPkts";
        }
        leaf out-multicast-pkts {
          type uint64;
          config false;
          status current;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             multicast address at this sub-layer, including those
             that were discarded or not sent.  For a MAC-layer
             protocol, this includes both Group and Functional
             addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutMulticastPkts";
        }
        leaf out-discards {
          type uint32;
          config false;
          status current;
          description
            "The number of outbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being transmitted.  One possible reason
             for discarding such a packet could be to free up buffer
             space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutDiscards";
        }
        leaf out-errors {
          type uint32;
          config false;
          status current;
          description
            "For packet-oriented interfaces, the number of outbound
             packets that could not be transmitted because of errors.
             For character-oriented or fixed-length interfaces, the
             number of outbound transmission units that could not be
             transmitted because of errors.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutErrors";
        }
      }
      container ipv4 {
        presence "true";
        config true;
        status current;
        description
          "Parameters for the IPv4 address family.";
        leaf enabled {
          type boolean;
          default "true";
          config true;
          status current;
          description
            "Controls whether IPv4 is enabled or disabled on this
             interface.  When IPv4 is enabled, this interface is
             connected to an IPv4 stack, and the interface can send
             and receive IPv4 packets.";
        }
        leaf forwarding {
          type boolean;
          default "false";
          config true;
          status current;
          description
            "Controls IPv4 packet forwarding of datagrams received by,
             but not addressed to, this interface.  IPv4 routers
             forward datagrams.  IPv4 hosts do not (except those
             source-routed via the host).";
        }
        leaf mtu {
          type uint16 {
            range "68..65535";
          }
          units "octets";
          config true;
          status current;
          description
            "The size, in octets, of the largest IPv4 packet that the
             interface will send and receive.

             The server may restrict the allowed values for this leaf,
             depending on the interface's type.

             If this leaf is not configured, the operationally used MTU
             depends on the interface's type.";
          reference
            "RFC 791: Internet Protocol";
        }
        list address {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "The list of IPv4 addresses on the interface.";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config true;
            status current;
            description
              "The IPv4 address on the interface.";
          }
          choice subnet {
            config true;
            mandatory true;
            status current;
            description
              "The subnet can be specified as a prefix length or,
               if the server supports non-contiguous netmasks, as
               a netmask.";
            case prefix-length {
              config true;
              status current;
              leaf prefix-length {
                type uint8 {
                  range "0..32";
                }
                config true;
                status current;
                description
                  "The length of the subnet prefix.";
              }
            }
            case netmask {
              config true;
              status current;
              leaf netmask {
                type string {
                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                }
                config true;
                status current;
                description
                  "The subnet specified as a netmask.";
              }
            }
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status current;
            description
              "The origin of this address.";
          }
        }
        list neighbor {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "A list of mappings from IPv4 addresses to
             link-layer addresses.

             Entries in this list in the intended configuration are
             used as static entries in the ARP Cache.

             In the operational state, this list represents the ARP
             Cache.";
          reference
            "RFC 826: An Ethernet Address Resolution Protocol";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config true;
            status current;
            description
              "The IPv4 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config true;
            mandatory true;
            status current;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status current;
            description
              "The origin of this neighbor entry.";
          }
        }
      }
      container ipv6 {
        presence "true";
        config true;
        status current;
        description
          "Parameters for the IPv6 address family.";
        leaf enabled {
          type boolean;
          default "true";
          config true;
          status current;
          description
            "Controls whether IPv6 is enabled or disabled on this
             interface.  When IPv6 is enabled, this interface is
             connected to an IPv6 stack, and the interface can send
             and receive IPv6 packets.";
        }
        leaf forwarding {
          type boolean;
          default "false";
          config true;
          status current;
          description
            "Controls IPv6 packet forwarding of datagrams received by,
             but not addressed to, this interface.  IPv6 routers
             forward datagrams.  IPv6 hosts do not (except those
             source-routed via the host).";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                       Section 6.2.1, IsRouter";
        }
        leaf mtu {
          type uint32 {
            range "1280..4294967295";
          }
          units "octets";
          config true;
          status current;
          description
            "The size, in octets, of the largest IPv6 packet that the
             interface will send and receive.

             The server may restrict the allowed values for this leaf,
             depending on the interface's type.

             If this leaf is not configured, the operationally used MTU
             depends on the interface's type.";
          reference
            "RFC 8200: Internet Protocol, Version 6 (IPv6)
                       Specification
                       Section 5";
        }
        list address {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "The list of IPv6 addresses on the interface.";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config true;
            status current;
            description
              "The IPv6 address on the interface.";
          }
          leaf prefix-length {
            type uint8 {
              range "0..128";
            }
            config true;
            mandatory true;
            status current;
            description
              "The length of the subnet prefix.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status current;
            description
              "The origin of this address.";
          }
          leaf status {
            type enumeration {
              enum "preferred" {
                value 0;
                status current;
                description
                  "This is a valid address that can appear as the
                   destination or source address of a packet.";
              }
              enum "deprecated" {
                value 1;
                status current;
                description
                  "This is a valid but deprecated address that should
                   no longer be used as a source address in new
                   communications, but packets addressed to such an
                   address are processed as expected.";
              }
              enum "invalid" {
                value 2;
                status current;
                description
                  "This isn't a valid address, and it shouldn't appear
                   as the destination or source address of a packet.";
              }
              enum "inaccessible" {
                value 3;
                status current;
                description
                  "The address is not accessible because the interface
                   to which this address is assigned is not
                   operational.";
              }
              enum "unknown" {
                value 4;
                status current;
                description
                  "The status cannot be determined for some reason.";
              }
              enum "tentative" {
                value 5;
                status current;
                description
                  "The uniqueness of the address on the link is being
                   verified.  Addresses in this state should not be
                   used for general communication and should only be
                   used to determine the uniqueness of the address.";
              }
              enum "duplicate" {
                value 6;
                status current;
                description
                  "The address has been determined to be non-unique on
                   the link and so must not be used.";
              }
              enum "optimistic" {
                value 7;
                status current;
                description
                  "The address is available for use, subject to
                   restrictions, while its uniqueness on a link is
                   being verified.";
              }
            }
            config false;
            status current;
            description
              "The status of an address.  Most of the states correspond
               to states from the IPv6 Stateless Address
               Autoconfiguration protocol.";
            reference
              "RFC 4293: Management Information Base for the
                         Internet Protocol (IP)
                         - IpAddressStatusTC
               RFC 4862: IPv6 Stateless Address Autoconfiguration";
          }
        }
        list neighbor {
          key "ip";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "A list of mappings from IPv6 addresses to
             link-layer addresses.

             Entries in this list in the intended configuration are
             used as static entries in the Neighbor Cache.

             In the operational state, this list represents the
             Neighbor Cache.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config true;
            status current;
            description
              "The IPv6 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config true;
            mandatory true;
            status current;
            description
              "The link-layer address of the neighbor node.

               In the operational state, if the neighbor's 'state' leaf
               is 'incomplete', this leaf is not instantiated.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status current;
            description
              "The origin of this neighbor entry.";
          }
          leaf is-router {
            type empty;
            config false;
            status current;
            description
              "Indicates that the neighbor node acts as a router.";
          }
          leaf state {
            type enumeration {
              enum "incomplete" {
                value 0;
                status current;
                description
                  "Address resolution is in progress, and the
                   link-layer address of the neighbor has not yet been
                   determined.";
              }
              enum "reachable" {
                value 1;
                status current;
                description
                  "Roughly speaking, the neighbor is known to have been
                   reachable recently (within tens of seconds ago).";
              }
              enum "stale" {
                value 2;
                status current;
                description
                  "The neighbor is no longer known to be reachable, but
                   until traffic is sent to the neighbor no attempt
                   should be made to verify its reachability.";
              }
              enum "delay" {
                value 3;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   traffic has recently been sent to the neighbor.
                   Rather than probe the neighbor immediately, however,
                   delay sending probes for a short while in order to
                   give upper-layer protocols a chance to provide
                   reachability confirmation.";
              }
              enum "probe" {
                value 4;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   unicast Neighbor Solicitation probes are being sent
                   to verify reachability.";
              }
            }
            config false;
            status current;
            description
              "The Neighbor Unreachability Detection state of this
               entry.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         Section 7.3.2";
          }
        }
        leaf dup-addr-detect-transmits {
          type uint32;
          default "1";
          config true;
          status current;
          description
            "The number of consecutive Neighbor Solicitation messages
             sent while performing Duplicate Address Detection on a
             tentative address.  A value of zero indicates that
             Duplicate Address Detection is not performed on
             tentative addresses.  A value of one indicates a single
             transmission with no follow-up retransmissions.";
          reference
            "RFC 4862: IPv6 Stateless Address Autoconfiguration";
        }
        container autoconf {
          config true;
          status current;
          description
            "Parameters to control the autoconfiguration of IPv6
             addresses, as described in RFC 4862.";
          reference
            "RFC 4862: IPv6 Stateless Address Autoconfiguration";
          leaf create-global-addresses {
            type boolean;
            default "true";
            config true;
            status current;
            description
              "If enabled, the host creates global addresses as
               described in RFC 4862.";
            reference
              "RFC 4862: IPv6 Stateless Address Autoconfiguration
                         Section 5.5";
          }
          leaf create-temporary-addresses {
            type boolean;
            default "false";
            config true;
            status current;
            description
              "If enabled, the host creates temporary addresses as
               described in RFC 4941.";
            reference
              "RFC 4941: Privacy Extensions for Stateless Address
                         Autoconfiguration in IPv6";
          }
          leaf temporary-valid-lifetime {
            type uint32;
            units "seconds";
            default "604800";
            config true;
            status current;
            description
              "The time period during which the temporary address
               is valid.";
            reference
              "RFC 4941: Privacy Extensions for Stateless Address
                         Autoconfiguration in IPv6
                         - TEMP_VALID_LIFETIME";
          }
          leaf temporary-preferred-lifetime {
            type uint32;
            units "seconds";
            default "86400";
            config true;
            status current;
            description
              "The time period during which the temporary address is
               preferred.";
            reference
              "RFC 4941: Privacy Extensions for Stateless Address
                         Autoconfiguration in IPv6
                         - TEMP_PREFERRED_LIFETIME";
          }
        }
        container ipv6-router-advertisements {
          config true;
          status current;
          description
            "Support for IPv6 Router Advertisements.";
          leaf send-advertisements {
            type boolean;
            default "false";
            config true;
            status current;
            description
              "A flag indicating whether or not the router sends
               periodic Router Advertisements and responds to
               Router Solicitations.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvSendAdvertisements";
          }
          leaf max-rtr-adv-interval {
            type uint16 {
              range "4..65535";
            }
            units "seconds";
            default "600";
            config true;
            status current;
            description
              "The maximum time allowed between sending unsolicited
               multicast Router Advertisements from the interface.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - MaxRtrAdvInterval";
          }
          leaf min-rtr-adv-interval {
            type uint16 {
              range "3..1350";
            }
            units "seconds";
            must ". <= 0.75 * ../max-rtr-adv-interval" {
              description
                "The value MUST NOT be greater than 75% of
                 'max-rtr-adv-interval'.";
            }
            config true;
            status current;
            description
              "The minimum time allowed between sending unsolicited
               multicast Router Advertisements from the interface.

               The default value to be used operationally if this
               leaf is not configured is determined as follows:

               - if max-rtr-adv-interval >= 9 seconds, the default
                 value is 0.33 * max-rtr-adv-interval;

               - otherwise, it is 0.75 * max-rtr-adv-interval.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - MinRtrAdvInterval";
          }
          leaf managed-flag {
            type boolean;
            default "false";
            config true;
            status current;
            description
              "The value to be placed in the 'Managed address
               configuration' flag field in the Router
               Advertisement.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvManagedFlag";
          }
          leaf other-config-flag {
            type boolean;
            default "false";
            config true;
            status current;
            description
              "The value to be placed in the 'Other configuration'
               flag field in the Router Advertisement.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvOtherConfigFlag";
          }
          leaf link-mtu {
            type uint32;
            default "0";
            config true;
            status current;
            description
              "The value to be placed in MTU options sent by the
               router.  A value of zero indicates that no MTU options
               are sent.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvLinkMTU";
          }
          leaf reachable-time {
            type uint32 {
              range "0..3600000";
            }
            units "milliseconds";
            default "0";
            config true;
            status current;
            description
              "The value to be placed in the Reachable Time field in
               the Router Advertisement messages sent by the router.
               A value of zero means unspecified (by this router).";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvReachableTime";
          }
          leaf retrans-timer {
            type uint32;
            units "milliseconds";
            default "0";
            config true;
            status current;
            description
              "The value to be placed in the Retrans Timer field in
               the Router Advertisement messages sent by the router.
               A value of zero means unspecified (by this router).";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvRetransTimer";
          }
          leaf cur-hop-limit {
            type uint8;
            config true;
            status current;
            description
              "The value to be placed in the Cur Hop Limit field in
               the Router Advertisement messages sent by the router.
               A value of zero means unspecified (by this router).

               If this parameter is not configured, the device SHOULD
               use the IANA-specified value for the default IPv4
               Time to Live (TTL) parameter that was in effect at the
               time of implementation.";
            reference
              "RFC 3232: Assigned Numbers: RFC 1700 is Replaced by
                         an On-line Database
               RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvCurHopLimit
               IANA: IP Parameters
                     (https://www.iana.org/assignments/ip-parameters)";
          }
          leaf default-lifetime {
            type uint16 {
              range "0..65535";
            }
            units "seconds";
            config true;
            status current;
            description
              "The value to be placed in the Router Lifetime field of
               Router Advertisements sent from the interface, in
               seconds.  It MUST be either zero or between
               max-rtr-adv-interval and 9000 seconds.  A value of zero
               indicates that the router is not to be used as a
               default router.  These limits may be overridden by
               specific documents that describe how IPv6 operates over
               different link layers.

               If this parameter is not configured, the device SHOULD
               use a value of 3 * max-rtr-adv-interval.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvDefaultLifetime";
          }
          container prefix-list {
            config true;
            status current;
            description
              "Support for prefixes to be placed in Prefix
               Information options in Router Advertisement messages
               sent from the interface.

               Prefixes that are advertised by default but do not
               have their entries in the child 'prefix' list are
               advertised with the default values of all parameters.

               The link-local prefix SHOULD NOT be included in the
               list of advertised prefixes.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         - AdvPrefixList";
            list prefix {
              key "prefix-spec";
              config true;
              min-elements 0;
              max-elements 4294967295;
              ordered-by system;
              status current;
              description
                "Support for an advertised prefix entry.";
              leaf prefix-spec {
                type string {
                  pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(/(([0-9])|([0-9]{2})|(1[0-1][0-9])|(12[0-8])))";
                  pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(/.+)";
                }
                config true;
                status current;
                description
                  "IPv6 address prefix.";
              }
              choice control-adv-prefixes {
                default "advertise";
                config true;
                status current;
                description
                  "Either (1) the prefix is explicitly removed from the
                   set of advertised prefixes or (2) the parameters with
                   which the prefix is advertised are specified (default
                   case).";
                case no-advertise {
                  config true;
                  status current;
                  leaf no-advertise {
                    type empty;
                    config true;
                    status current;
                    description
                      "The prefix will not be advertised.

                       This can be used for removing the prefix from
                       the default set of advertised prefixes.";
                  }
                }
                case advertise {
                  config true;
                  status current;
                  leaf valid-lifetime {
                    type uint32;
                    units "seconds";
                    default "2592000";
                    config true;
                    status current;
                    description
                      "The value to be placed in the Valid Lifetime
                       in the Prefix Information option.  The
                       designated value of all 1's (0xffffffff)
                        represents infinity.";
                    reference
                      "RFC 4861: Neighbor Discovery for IP version 6
                                 (IPv6) - AdvValidLifetime";
                  }
                  leaf on-link-flag {
                    type boolean;
                    default "true";
                    config true;
                    status current;
                    description
                      "The value to be placed in the on-link flag
                       ('L-bit') field in the Prefix Information
                       option.";
                    reference
                      "RFC 4861: Neighbor Discovery for IP version 6
                                 (IPv6) - AdvOnLinkFlag";
                  }
                  leaf preferred-lifetime {
                    type uint32;
                    units "seconds";
                    must ". <= ../valid-lifetime" {
                      description
                        "This value MUST NOT be greater than
                         valid-lifetime.";
                    }
                    default "604800";
                    config true;
                    status current;
                    description
                      "The value to be placed in the Preferred
                       Lifetime in the Prefix Information option.
                       The designated value of all 1's (0xffffffff)
                       represents infinity.";
                    reference
                      "RFC 4861: Neighbor Discovery for IP version 6
                                 (IPv6) - AdvPreferredLifetime";
                  }
                  leaf autonomous-flag {
                    type boolean;
                    default "true";
                    config true;
                    status current;
                    description
                      "The value to be placed in the Autonomous Flag
                       field in the Prefix Information option.";
                    reference
                      "RFC 4861: Neighbor Discovery for IP version 6
                                 (IPv6) - AdvAutonomousFlag";
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  container interfaces-state {
    config false;
    status deprecated;
    description
      "Data nodes for the operational state of interfaces.";
    list interface {
      key "name";
      config false;
      min-elements 0;
      max-elements 4294967295;
      ordered-by user;
      status deprecated;
      description
        "The list of interfaces on the device.

         System-controlled interfaces created by the system are
         always present in this list, whether or not they are
         configured.";
      leaf name {
        type string;
        config false;
        status deprecated;
        description
          "The name of the interface.

           A server implementation MAY map this leaf to the ifName
           MIB object.  Such an implementation needs to use some
           mechanism to handle the differences in size and characters
           allowed between this leaf and ifName.  The definition of
           such a mechanism is outside the scope of this document.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifName";
      }
      leaf type {
        type identityref {
          base interface-type;
        }
        config false;
        mandatory true;
        status deprecated;
        description
          "The type of the interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifType";
      }
      leaf admin-status {
        type enumeration {
          enum "up" {
            value 1;
            status current;
            description
              "Ready to pass packets.";
          }
          enum "down" {
            value 2;
            status current;
            description
              "Not ready to pass packets and not in some test mode.";
          }
          enum "testing" {
            value 3;
            status current;
            description
              "In some test mode.";
          }
        }
        config false;
        mandatory true;
        status deprecated;
        description
          "The desired state of the interface.

           This leaf has the same read semantics as ifAdminStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifAdminStatus";
      }
      leaf oper-status {
        type enumeration {
          enum "up" {
            value 1;
            status current;
            description
              "Ready to pass packets.";
          }
          enum "down" {
            value 2;
            status current;
            description
              "The interface does not pass any packets.";
          }
          enum "testing" {
            value 3;
            status current;
            description
              "In some test mode.  No operational packets can
               be passed.";
          }
          enum "unknown" {
            value 4;
            status current;
            description
              "Status cannot be determined for some reason.";
          }
          enum "dormant" {
            value 5;
            status current;
            description
              "Waiting for some external event.";
          }
          enum "not-present" {
            value 6;
            status current;
            description
              "Some component (typically hardware) is missing.";
          }
          enum "lower-layer-down" {
            value 7;
            status current;
            description
              "Down due to state of lower-layer interface(s).";
          }
        }
        config false;
        mandatory true;
        status deprecated;
        description
          "The current operational state of the interface.

           This leaf has the same semantics as ifOperStatus.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifOperStatus";
      }
      leaf last-change {
        type string {
          pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
        }
        config false;
        status deprecated;
        description
          "The time the interface entered its current operational
           state.  If the current state was entered prior to the
           last re-initialization of the local network management
           subsystem, then this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifLastChange";
      }
      leaf if-index {
        type int32 {
          range "1..2147483647";
        }
        config false;
        mandatory true;
        status deprecated;
        description
          "The ifIndex value for the ifEntry represented by this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifIndex";
      }
      leaf phys-address {
        type string {
          pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
        }
        config false;
        status deprecated;
        description
          "The interface's address at its protocol sub-layer.  For
           example, for an 802.x interface, this object normally
           contains a Media Access Control (MAC) address.  The
           interface's media-specific modules must define the bit
           and byte ordering and the format of the value of this
           object.  For interfaces that do not have such an address
           (e.g., a serial line), this node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifPhysAddress";
      }
      leaf-list higher-layer-if {
        type leafref {
          path "/if:interfaces-state/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status deprecated;
        description
          "A list of references to interfaces layered on top of this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf-list lower-layer-if {
        type leafref {
          path "/if:interfaces-state/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status deprecated;
        description
          "A list of references to interfaces layered underneath this
           interface.";
        reference
          "RFC 2863: The Interfaces Group MIB - ifStackTable";
      }
      leaf speed {
        type uint64;
        units "bits/second";
        config false;
        status deprecated;
        description
          "An estimate of the interface's current bandwidth in bits
           per second.  For interfaces that do not vary in
           bandwidth or for those where no accurate estimation can

           be made, this node should contain the nominal bandwidth.
           For interfaces that have no concept of bandwidth, this
           node is not present.";
        reference
          "RFC 2863: The Interfaces Group MIB -
                     ifSpeed, ifHighSpeed";
      }
      container statistics {
        config false;
        status deprecated;
        description
          "A collection of interface-related statistics objects.";
        leaf discontinuity-time {
          type string {
            pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
          }
          config false;
          mandatory true;
          status deprecated;
          description
            "The time on the most recent occasion at which any one or
             more of this interface's counters suffered a
             discontinuity.  If no such discontinuities have occurred
             since the last re-initialization of the local management
             subsystem, then this node contains the time the local
             management subsystem re-initialized itself.";
        }
        leaf in-octets {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of octets received on the interface,
             including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInOctets";
        }
        leaf in-unicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were not addressed to a
             multicast or broadcast address at this sub-layer.
             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCInUcastPkts";
        }
        leaf in-broadcast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a broadcast
             address at this sub-layer.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInBroadcastPkts";
        }
        leaf in-multicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The number of packets, delivered by this sub-layer to a
             higher (sub-)layer, that were addressed to a multicast
             address at this sub-layer.  For a MAC-layer protocol,
             this includes both Group and Functional addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCInMulticastPkts";
        }
        leaf in-discards {
          type uint32;
          config false;
          status deprecated;
          description
            "The number of inbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being deliverable to a higher-layer
             protocol.  One possible reason for discarding such a
             packet could be to free up buffer space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInDiscards";
        }
        leaf in-errors {
          type uint32;
          config false;
          status deprecated;
          description
            "For packet-oriented interfaces, the number of inbound
             packets that contained errors preventing them from being
             deliverable to a higher-layer protocol.  For character-
             oriented or fixed-length interfaces, the number of
             inbound transmission units that contained errors
             preventing them from being deliverable to a higher-layer
             protocol.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInErrors";
        }
        leaf in-unknown-protos {
          type uint32;
          config false;
          status deprecated;
          description
            "For packet-oriented interfaces, the number of packets
             received via the interface that were discarded because
             of an unknown or unsupported protocol.  For
             character-oriented or fixed-length interfaces that
             support protocol multiplexing, the number of
             transmission units received via the interface that were
             discarded because of an unknown or unsupported protocol.
             For any interface that does not support protocol
             multiplexing, this counter is not present.
             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifInUnknownProtos";
        }
        leaf out-octets {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of octets transmitted out of the
             interface, including framing characters.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutOctets";
        }
        leaf out-unicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were not addressed
             to a multicast or broadcast address at this sub-layer,
             including those that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifHCOutUcastPkts";
        }
        leaf out-broadcast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             broadcast address at this sub-layer, including those
             that were discarded or not sent.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutBroadcastPkts";
        }
        leaf out-multicast-pkts {
          type uint64;
          config false;
          status deprecated;
          description
            "The total number of packets that higher-level protocols
             requested be transmitted and that were addressed to a
             multicast address at this sub-layer, including those
             that were discarded or not sent.  For a MAC-layer
             protocol, this includes both Group and Functional
             addresses.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB -
                       ifHCOutMulticastPkts";
        }
        leaf out-discards {
          type uint32;
          config false;
          status deprecated;
          description
            "The number of outbound packets that were chosen to be
             discarded even though no errors had been detected to
             prevent their being transmitted.  One possible reason
             for discarding such a packet could be to free up buffer
             space.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutDiscards";
        }
        leaf out-errors {
          type uint32;
          config false;
          status deprecated;
          description
            "For packet-oriented interfaces, the number of outbound
             packets that could not be transmitted because of errors.
             For character-oriented or fixed-length interfaces, the
             number of outbound transmission units that could not be
             transmitted because of errors.

             Discontinuities in the value of this counter can occur
             at re-initialization of the management system and at
             other times as indicated by the value of
             'discontinuity-time'.";
          reference
            "RFC 2863: The Interfaces Group MIB - ifOutErrors";
        }
      }
      container ipv4 {
        presence "true";
        config false;
        status deprecated;
        description
          "Interface-specific parameters for the IPv4 address family.";
        leaf forwarding {
          type boolean;
          config false;
          status deprecated;
          description
            "Indicates whether IPv4 packet forwarding is enabled or
             disabled on this interface.";
        }
        leaf mtu {
          type uint16 {
            range "68..65535";
          }
          units "octets";
          config false;
          status deprecated;
          description
            "The size, in octets, of the largest IPv4 packet that the
             interface will send and receive.";
          reference
            "RFC 791: Internet Protocol";
        }
        list address {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "The list of IPv4 addresses on the interface.";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv4 address on the interface.";
          }
          choice subnet {
            config false;
            status deprecated;
            description
              "The subnet can be specified as a prefix length or,
               if the server supports non-contiguous netmasks, as
               a netmask.";
            case prefix-length {
              config false;
              status deprecated;
              leaf prefix-length {
                type uint8 {
                  range "0..32";
                }
                config false;
                status deprecated;
                description
                  "The length of the subnet prefix.";
              }
            }
            case netmask {
              config false;
              status deprecated;
              leaf netmask {
                type string {
                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                }
                config false;
                status deprecated;
                description
                  "The subnet specified as a netmask.";
              }
            }
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this address.";
          }
        }
        list neighbor {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "A list of mappings from IPv4 addresses to
             link-layer addresses.

             This list represents the ARP Cache.";
          reference
            "RFC 826: An Ethernet Address Resolution Protocol";
          leaf ip {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              pattern "[0-9\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv4 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config false;
            status deprecated;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this neighbor entry.";
          }
        }
      }
      container ipv6 {
        presence "true";
        config false;
        status deprecated;
        description
          "Parameters for the IPv6 address family.";
        leaf forwarding {
          type boolean;
          default "false";
          config false;
          status deprecated;
          description
            "Indicates whether IPv6 packet forwarding is enabled or
             disabled on this interface.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                       Section 6.2.1, IsRouter";
        }
        leaf mtu {
          type uint32 {
            range "1280..4294967295";
          }
          units "octets";
          config false;
          status deprecated;
          description
            "The size, in octets, of the largest IPv6 packet that the
             interface will send and receive.";
          reference
            "RFC 8200: Internet Protocol, Version 6 (IPv6)
                       Specification
                       Section 5";
        }
        list address {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "The list of IPv6 addresses on the interface.";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv6 address on the interface.";
          }
          leaf prefix-length {
            type uint8 {
              range "0..128";
            }
            config false;
            mandatory true;
            status deprecated;
            description
              "The length of the subnet prefix.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the address has been statically
                   configured -- for example, using the Network Configuration
                   Protocol (NETCONF) or a command line interface.";
              }
              enum "dhcp" {
                value 2;
                status current;
                description
                  "Indicates an address that has been assigned to this
                   system by a DHCP server.";
              }
              enum "link-layer" {
                value 3;
                status current;
                description
                  "Indicates an address created by IPv6 stateless
                   autoconfiguration that embeds a link-layer address in its
                   interface identifier.";
              }
              enum "random" {
                value 4;
                status current;
                description
                  "Indicates an address chosen by the system at
                   random, e.g., an IPv4 address within 169.254/16, a
                   temporary address as described in RFC 4941, or a
                   semantically opaque address as described in RFC 7217.";
                reference
                  "RFC 4941: Privacy Extensions for Stateless Address
                             Autoconfiguration in IPv6
                   RFC 7217: A Method for Generating Semantically Opaque
                             Interface Identifiers with IPv6 Stateless
                             Address Autoconfiguration (SLAAC)";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this address.";
          }
          leaf status {
            type enumeration {
              enum "preferred" {
                value 0;
                status current;
                description
                  "This is a valid address that can appear as the
                   destination or source address of a packet.";
              }
              enum "deprecated" {
                value 1;
                status current;
                description
                  "This is a valid but deprecated address that should
                   no longer be used as a source address in new
                   communications, but packets addressed to such an
                   address are processed as expected.";
              }
              enum "invalid" {
                value 2;
                status current;
                description
                  "This isn't a valid address, and it shouldn't appear
                   as the destination or source address of a packet.";
              }
              enum "inaccessible" {
                value 3;
                status current;
                description
                  "The address is not accessible because the interface
                   to which this address is assigned is not
                   operational.";
              }
              enum "unknown" {
                value 4;
                status current;
                description
                  "The status cannot be determined for some reason.";
              }
              enum "tentative" {
                value 5;
                status current;
                description
                  "The uniqueness of the address on the link is being
                   verified.  Addresses in this state should not be
                   used for general communication and should only be
                   used to determine the uniqueness of the address.";
              }
              enum "duplicate" {
                value 6;
                status current;
                description
                  "The address has been determined to be non-unique on
                   the link and so must not be used.";
              }
              enum "optimistic" {
                value 7;
                status current;
                description
                  "The address is available for use, subject to
                   restrictions, while its uniqueness on a link is
                   being verified.";
              }
            }
            config false;
            status deprecated;
            description
              "The status of an address.  Most of the states correspond
               to states from the IPv6 Stateless Address
               Autoconfiguration protocol.";
            reference
              "RFC 4293: Management Information Base for the
                         Internet Protocol (IP)
                         - IpAddressStatusTC
               RFC 4862: IPv6 Stateless Address Autoconfiguration";
          }
        }
        list neighbor {
          key "ip";
          config false;
          min-elements 0;
          max-elements 4294967295;
          ordered-by user;
          status deprecated;
          description
            "A list of mappings from IPv6 addresses to
             link-layer addresses.

             This list represents the Neighbor Cache.";
          reference
            "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)";
          leaf ip {
            type string {
              pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
              pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              pattern "[0-9a-fA-F:\\.]*";
            }
            config false;
            status deprecated;
            description
              "The IPv6 address of the neighbor node.";
          }
          leaf link-layer-address {
            type string {
              pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
            }
            config false;
            status deprecated;
            description
              "The link-layer address of the neighbor node.";
          }
          leaf origin {
            type enumeration {
              enum "other" {
                value 0;
                status current;
                description
                  "None of the following.";
              }
              enum "static" {
                value 1;
                status current;
                description
                  "Indicates that the mapping has been statically
                   configured -- for example, using NETCONF or a command line
                   interface.";
              }
              enum "dynamic" {
                value 2;
                status current;
                description
                  "Indicates that the mapping has been dynamically resolved
                   using, for example, IPv4 ARP or the IPv6 Neighbor
                   Discovery protocol.";
              }
            }
            config false;
            status deprecated;
            description
              "The origin of this neighbor entry.";
          }
          leaf is-router {
            type empty;
            config false;
            status deprecated;
            description
              "Indicates that the neighbor node acts as a router.";
          }
          leaf state {
            type enumeration {
              enum "incomplete" {
                value 0;
                status current;
                description
                  "Address resolution is in progress, and the
                   link-layer address of the neighbor has not yet been
                   determined.";
              }
              enum "reachable" {
                value 1;
                status current;
                description
                  "Roughly speaking, the neighbor is known to have been
                   reachable recently (within tens of seconds ago).";
              }
              enum "stale" {
                value 2;
                status current;
                description
                  "The neighbor is no longer known to be reachable, but
                   until traffic is sent to the neighbor no attempt
                   should be made to verify its reachability.";
              }
              enum "delay" {
                value 3;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   traffic has recently been sent to the neighbor.
                   Rather than probe the neighbor immediately, however,
                   delay sending probes for a short while in order to
                   give upper-layer protocols a chance to provide
                   reachability confirmation.";
              }
              enum "probe" {
                value 4;
                status current;
                description
                  "The neighbor is no longer known to be reachable, and
                   unicast Neighbor Solicitation probes are being sent
                   to verify reachability.";
              }
            }
            config false;
            status deprecated;
            description
              "The Neighbor Unreachability Detection state of this
               entry.";
            reference
              "RFC 4861: Neighbor Discovery for IP version 6 (IPv6)
                         Section 7.3.2";
          }
        }
      }
    }
  }
