module ietf-routing {
  namespace "urn:ietf:params:xml:ns:yang:ietf-routing";
  prefix rt;

  organization
    "IETF NETMOD (Network Modeling) Working Group";
  contact
    "WG Web:   <https://datatracker.ietf.org/wg/netmod/>
     WG List:  <mailto:rtgwg@ietf.org>

     Editor:   Ladislav Lhotka
               <mailto:lhotka@nic.cz>
               Acee Lindem
               <mailto:acee@cisco.com>
               Yingzhen Qu
               <mailto:yingzhen.qu@huawei.com>";
  description
    "This YANG module defines essential components for the management
     of a routing subsystem.  The model fully conforms to the Network
     Management Datastore Architecture (NMDA).

     Copyright (c) 2018 IETF Trust and the persons
     identified as authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).
     This version of this YANG module is part of RFC 8349; see
     the RFC itself for full legal notices.";

  revision 2018-03-13;

  identity address-family {
    derived ipv4;
    derived ipv6;
    description
      "Base identity from which identities describing address
       families are derived.";
  }

  identity ipv4 {
    description
      "This identity represents an IPv4 address family.";
  }

  identity ipv6 {
    derived v6ur:ipv6-unicast;
    description
      "This identity represents an IPv6 address family.";
  }

  identity control-plane-protocol {
    derived routing-protocol;
    description
      "Base identity from which control-plane protocol identities are
       derived.";
  }

  identity routing-protocol {
    derived direct;
    derived static;
    description
      "Identity from which Layer 3 routing protocol identities are
       derived.";
  }

  identity direct {
    description
      "Routing pseudo-protocol that provides routes to directly
       connected networks.";
  }

  identity static {
    description
      "'Static' routing pseudo-protocol.";
  }

  container routing {
    config true;
    status current;
    description
      "Configuration parameters for the routing subsystem.";
    leaf router-id {
      type string {
        pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
      }
      config true;
      status current;
      description
        "A 32-bit number in the form of a dotted quad that is used by
         some routing protocols identifying a router.";
      reference
        "RFC 2328: OSPF Version 2";
    }
    container interfaces {
      config false;
      status current;
      description
        "Network-layer interfaces used for routing.";
      leaf-list interface {
        type leafref {
          path "/if:interfaces/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "Each entry is a reference to the name of a configured
           network-layer interface.";
      }
    }
    container control-plane-protocols {
      config true;
      status current;
      description
        "Support for control-plane protocol instances.";
      list control-plane-protocol {
        key "typename";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "Each entry contains a control-plane protocol instance.";
        leaf type {
          type identityref {
            base control-plane-protocol;
          }
          config true;
          status current;
          description
            "Type of the control-plane protocol -- an identity
             derived from the 'control-plane-protocol'
             base identity.";
        }
        leaf name {
          type string;
          config true;
          status current;
          description
            "An arbitrary name of the control-plane protocol
             instance.";
        }
        leaf description {
          type string;
          config true;
          status current;
          description
            "Textual description of the control-plane protocol
             instance.";
        }
        container static-routes {
          when "derived-from-or-self(../type, 'rt:static')" {
            description
              "This container is only valid for the 'static' routing
               protocol.";
          }
          config true;
          status current;
          description
            "Support for the 'static' pseudo-protocol.

             Address-family-specific modules augment this node with
             their lists of routes.";
          container ipv6 {
            config true;
            status current;
            description
              "Support for a 'static' pseudo-protocol instance
               consists of a list of routes.";
            list route {
              key "destination-prefix";
              config true;
              min-elements 0;
              max-elements 4294967295;
              ordered-by system;
              status current;
              description
                "A list of static routes.";
              leaf destination-prefix {
                type string {
                  pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(/(([0-9])|([0-9]{2})|(1[0-1][0-9])|(12[0-8])))";
                  pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(/.+)";
                }
                config true;
                mandatory true;
                status current;
                description
                  "IPv6 destination prefix.";
              }
              leaf description {
                type string;
                config true;
                status current;
                description
                  "Textual description of the route.";
              }
              container next-hop {
                config true;
                status current;
                description
                  "Next hop for the route.";
                choice next-hop-options {
                  config true;
                  mandatory true;
                  status current;
                  description
                    "Options for next hops in static routes.

                     It is expected that further cases will be added through
                     augments from other modules.";
                  case simple-next-hop {
                    config true;
                    status current;
                    description
                      "This case represents a simple next hop consisting of the
                       next-hop address and/or outgoing interface.

                       Modules for address families MUST augment this case with a
                       leaf containing a next-hop address of that address
                       family.";
                    leaf outgoing-interface {
                      type leafref {
                        path "/if:interfaces/if:interface/if:name";
                        require-instance true;
                        type string;
                      }
                      config true;
                      status current;
                      description
                        "Name of the outgoing interface.";
                    }
                    leaf next-hop-address {
                      type string {
                        pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                        pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                      }
                      config true;
                      status current;
                      description
                        "IPv6 address of the next hop.";
                    }
                  }
                  case special-next-hop {
                    config true;
                    status current;
                    leaf special-next-hop {
                      type enumeration {
                        enum "blackhole" {
                          value 0;
                          status current;
                          description
                            "Silently discard the packet.";
                        }
                        enum "unreachable" {
                          value 1;
                          status current;
                          description
                            "Discard the packet and notify the sender with an error
                             message indicating that the destination host is
                             unreachable.";
                        }
                        enum "prohibit" {
                          value 2;
                          status current;
                          description
                            "Discard the packet and notify the sender with an error
                             message indicating that the communication is
                             administratively prohibited.";
                        }
                        enum "receive" {
                          value 3;
                          status current;
                          description
                            "The packet will be received by the local system.";
                        }
                      }
                      config true;
                      status current;
                      description
                        "Options for special next hops.";
                    }
                  }
                  case next-hop-list {
                    config true;
                    status current;
                    container next-hop-list {
                      config true;
                      status current;
                      description
                        "Container for multiple next hops.";
                      list next-hop {
                        key "index";
                        config true;
                        min-elements 0;
                        max-elements 4294967295;
                        ordered-by system;
                        status current;
                        description
                          "An entry in a next-hop list.

                           Modules for address families MUST augment this list
                           with a leaf containing a next-hop address of that
                           address family.";
                        leaf index {
                          type string;
                          config true;
                          status current;
                          description
                            "A user-specified identifier utilized to uniquely
                             reference the next-hop entry in the next-hop list.
                             The value of this index has no semantic meaning
                             other than for referencing the entry.";
                        }
                        leaf outgoing-interface {
                          type leafref {
                            path "/if:interfaces/if:interface/if:name";
                            require-instance true;
                            type string;
                          }
                          config true;
                          status current;
                          description
                            "Name of the outgoing interface.";
                        }
                        leaf next-hop-address {
                          type string {
                            pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                            pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                          }
                          config true;
                          status current;
                          description
                            "IPv6 address of the next hop.";
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
    container ribs {
      config true;
      status current;
      description
        "Support for RIBs.";
      list rib {
        key "name";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "Each entry contains a configuration for a RIB identified
           by the 'name' key.

           Entries having the same key as a system-controlled entry
           in the list '/routing/ribs/rib' are used for
           configuring parameters of that entry.  Other entries
           define additional user-controlled RIBs.";
        leaf name {
          type string;
          config true;
          status current;
          description
            "The name of the RIB.

             For system-controlled entries, the value of this leaf
             must be the same as the name of the corresponding entry
             in the operational state.

             For user-controlled entries, an arbitrary name can be
             used.";
        }
        leaf address-family {
          type identityref {
            base address-family;
          }
          config true;
          mandatory true;
          status current;
          description
            "Address family.";
        }
        leaf default-rib {
          type boolean;
          default "true";
          config false;
          status current;
          description
            "This flag has the value of 'true' if and only if the RIB
             is the default RIB for the given address family.

             By default, control-plane protocols place their routes
             in the default RIBs.";
        }
        container routes {
          config false;
          status current;
          description
            "Current contents of the RIB.";
          list route {
            config false;
            min-elements 0;
            max-elements 4294967295;
            ordered-by user;
            status current;
            description
              "A RIB route entry.  This data node MUST be augmented
               with information specific to routes of each address
               family.";
            leaf route-preference {
              type uint32;
              config false;
              status current;
              description
                "This route attribute, also known as 'administrative
                 distance', allows for selecting the preferred route
                 among routes with the same destination prefix.  A
                 smaller value indicates a route that is
                 more preferred.";
            }
            container next-hop {
              config false;
              status current;
              description
                "Route's next-hop attribute.";
              choice next-hop-options {
                config false;
                mandatory true;
                status current;
                description
                  "Options for next hops.

                   It is expected that further cases will be added through
                   augments from other modules, e.g., for recursive
                   next hops.";
                case simple-next-hop {
                  config false;
                  status current;
                  description
                    "This case represents a simple next hop consisting of the
                     next-hop address and/or outgoing interface.

                     Modules for address families MUST augment this case with a
                     leaf containing a next-hop address of that address
                     family.";
                  leaf outgoing-interface {
                    type leafref {
                      path "/if:interfaces/if:interface/if:name";
                      require-instance true;
                      type string;
                    }
                    config false;
                    status current;
                    description
                      "Name of the outgoing interface.";
                  }
                  leaf next-hop-address {
                    when "derived-from-or-self(../../../rt:address-family, 'v6ur:ipv6-unicast')" {
                      description
                        "This augment is valid only for IPv6 unicast.";
                    }
                    type string {
                      pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                      pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                    }
                    config false;
                    status current;
                    description
                      "IPv6 address of the next hop.";
                  }
                }
                case special-next-hop {
                  config false;
                  status current;
                  leaf special-next-hop {
                    type enumeration {
                      enum "blackhole" {
                        value 0;
                        status current;
                        description
                          "Silently discard the packet.";
                      }
                      enum "unreachable" {
                        value 1;
                        status current;
                        description
                          "Discard the packet and notify the sender with an error
                           message indicating that the destination host is
                           unreachable.";
                      }
                      enum "prohibit" {
                        value 2;
                        status current;
                        description
                          "Discard the packet and notify the sender with an error
                           message indicating that the communication is
                           administratively prohibited.";
                      }
                      enum "receive" {
                        value 3;
                        status current;
                        description
                          "The packet will be received by the local system.";
                      }
                    }
                    config false;
                    status current;
                    description
                      "Options for special next hops.";
                  }
                }
                case next-hop-list {
                  config false;
                  status current;
                  container next-hop-list {
                    config false;
                    status current;
                    description
                      "Container for multiple next hops.";
                    list next-hop {
                      config false;
                      min-elements 0;
                      max-elements 4294967295;
                      ordered-by user;
                      status current;
                      description
                        "An entry in a next-hop list.

                         Modules for address families MUST augment this list
                         with a leaf containing a next-hop address of that
                         address family.";
                      leaf outgoing-interface {
                        type leafref {
                          path "/if:interfaces/if:interface/if:name";
                          require-instance true;
                          type string;
                        }
                        config false;
                        status current;
                        description
                          "Name of the outgoing interface.";
                      }
                      leaf address {
                        when "derived-from-or-self(../../../../../rt:address-family, 'v6ur:ipv6-unicast')" {
                          description
                            "This augment is valid only for IPv6 unicast.";
                        }
                        type string {
                          pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                          pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                        }
                        config false;
                        status current;
                        description
                          "IPv6 address of the next hop.";
                      }
                    }
                  }
                }
              }
            }
            leaf source-protocol {
              type identityref {
                base routing-protocol;
              }
              config false;
              mandatory true;
              status current;
              description
                "Type of the routing protocol from which the route
                 originated.";
            }
            leaf active {
              type empty;
              config false;
              status current;
              description
                "The presence of this leaf indicates that the route is
                 preferred among all routes in the same RIB that have the
                 same destination prefix.";
            }
            leaf last-updated {
              type string {
                pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
              }
              config false;
              status current;
              description
                "Timestamp of the last modification of the route.  If the
                 route was never modified, it is the time when the route was
                 inserted into the RIB.";
            }
            leaf destination-prefix {
              when "derived-from-or-self(../../rt:address-family, 'v6ur:ipv6-unicast')" {
                description
                  "This augment is valid only for IPv6 unicast.";
              }
              type string {
                pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(/(([0-9])|([0-9]{2})|(1[0-1][0-9])|(12[0-8])))";
                pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(/.+)";
              }
              config false;
              status current;
              description
                "IPv6 destination prefix.";
            }
          }
        }
        leaf description {
          type string;
          config true;
          status current;
          description
            "Textual description of the RIB.";
        }
        action active-route {
          status current;
          description
            "Return the active RIB route that is used for the
             destination address.

             Address-family-specific modules MUST augment input
             parameters with a leaf named 'destination-address'.";

          input {
            leaf destination-address {
              when "derived-from-or-self(../rt:address-family, 'v6ur:ipv6-unicast')" {
                description
                  "This augment is valid only for IPv6 unicast RIBs.";
              }
              type string {
                pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              }
              status current;
              description
                "IPv6 destination address.";
            }
          }

          output {
            container route {
              status current;
              description
                "The active RIB route for the specified destination.

                 If no route exists in the RIB for the destination
                 address, no output is returned.

                 Address-family-specific modules MUST augment this
                 container with appropriate route contents.";
              container next-hop {
                status current;
                description
                  "Route's next-hop attribute.";
                choice next-hop-options {
                  mandatory true;
                  status current;
                  description
                    "Options for next hops.

                     It is expected that further cases will be added through
                     augments from other modules, e.g., for recursive
                     next hops.";
                  case simple-next-hop {
                    status current;
                    description
                      "This case represents a simple next hop consisting of the
                       next-hop address and/or outgoing interface.

                       Modules for address families MUST augment this case with a
                       leaf containing a next-hop address of that address
                       family.";
                    leaf outgoing-interface {
                      type leafref {
                        path "/if:interfaces/if:interface/if:name";
                        require-instance true;
                        type string;
                      }
                      status current;
                      description
                        "Name of the outgoing interface.";
                    }
                    leaf next-hop-address {
                      when "derived-from-or-self(../../../rt:address-family, 'v6ur:ipv6-unicast')" {
                        description
                          "This augment is valid only for IPv6 unicast.";
                      }
                      type string {
                        pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                        pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                      }
                      status current;
                      description
                        "IPv6 address of the next hop.";
                    }
                  }
                  case special-next-hop {
                    status current;
                    leaf special-next-hop {
                      type enumeration {
                        enum "blackhole" {
                          value 0;
                          status current;
                          description
                            "Silently discard the packet.";
                        }
                        enum "unreachable" {
                          value 1;
                          status current;
                          description
                            "Discard the packet and notify the sender with an error
                             message indicating that the destination host is
                             unreachable.";
                        }
                        enum "prohibit" {
                          value 2;
                          status current;
                          description
                            "Discard the packet and notify the sender with an error
                             message indicating that the communication is
                             administratively prohibited.";
                        }
                        enum "receive" {
                          value 3;
                          status current;
                          description
                            "The packet will be received by the local system.";
                        }
                      }
                      status current;
                      description
                        "Options for special next hops.";
                    }
                  }
                  case next-hop-list {
                    status current;
                    container next-hop-list {
                      status current;
                      description
                        "Container for multiple next hops.";
                      list next-hop {
                        min-elements 0;
                        max-elements 4294967295;
                        ordered-by user;
                        status current;
                        description
                          "An entry in a next-hop list.

                           Modules for address families MUST augment this list
                           with a leaf containing a next-hop address of that
                           address family.";
                        leaf outgoing-interface {
                          type leafref {
                            path "/if:interfaces/if:interface/if:name";
                            require-instance true;
                            type string;
                          }
                          status current;
                          description
                            "Name of the outgoing interface.";
                        }
                        leaf next-hop-address {
                          when "derived-from-or-self(../../../../../rt:address-family, 'v6ur:ipv6-unicast')" {
                            description
                              "This augment is valid only for IPv6 unicast.";
                          }
                          type string {
                            pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                            pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                          }
                          status current;
                          description
                            "IPv6 address of the next hop.";
                        }
                      }
                    }
                  }
                }
              }
              leaf source-protocol {
                type identityref {
                  base routing-protocol;
                }
                mandatory true;
                status current;
                description
                  "Type of the routing protocol from which the route
                   originated.";
              }
              leaf active {
                type empty;
                status current;
                description
                  "The presence of this leaf indicates that the route is
                   preferred among all routes in the same RIB that have the
                   same destination prefix.";
              }
              leaf last-updated {
                type string {
                  pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
                }
                status current;
                description
                  "Timestamp of the last modification of the route.  If the
                   route was never modified, it is the time when the route was
                   inserted into the RIB.";
              }
              leaf destination-prefix {
                when "derived-from-or-self(../../rt:address-family, 'v6ur:ipv6-unicast')" {
                  description
                    "This augment is valid only for IPv6 unicast.";
                }
                type string {
                  pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(/(([0-9])|([0-9]{2})|(1[0-1][0-9])|(12[0-8])))";
                  pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(/.+)";
                }
                status current;
                description
                  "IPv6 destination prefix.";
              }
            }
          }
        }
      }
    }
  }
}

